const { useState } = React;

function App() {
  const [page, setPage] = useState("profile");

  // Controlled form state for Edit Profile
  const [name, setName] = useState("Alex Kim");
  const [handle, setHandle] = useState("alexk");
  const [errors, setErrors] = useState({});

  // Static data for counts and posts
  const postsCount = 120;
  const followersCount = "4.5k";
  const followingCount = 300;

  // Photos keys for posts grid
  const postPhotos = ["travel", "food", "nature"];

  function validate() {
    const newErrors = {};
    if (!name.trim()) newErrors.name = "Name is required.";
    if (!handle.trim()) newErrors.handle = "Handle is required.";
    else if (!/^\w{1,15}$/.test(handle)) newErrors.handle = "Handle must be 1-15 characters, letters, numbers or underscore.";
    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  }

  function onSave(e) {
    e.preventDefault();
    if (validate()) {
      setPage("profile");
    }
  }

  if (page === "profile") {
    return (
      <main style={styles.main}>
        <header style={styles.coverContainer}>
          <img
            src="/runtime/photos/banner.jpg"
            alt="Cover"
            style={styles.coverImage}
          />
        </header>

        <section style={styles.profileHeader}>
          <img
            src="/runtime/photos/person.jpg"
            alt="Avatar"
            style={styles.avatar}
          />
          <div style={styles.nameHandleContainer}>
            <h2 style={styles.name}>{name}</h2>
            <p style={styles.handle}>@{handle}</p>
          </div>
          <button
            style={styles.editButton}
            onClick={() => setPage("edit")}
            aria-label="Edit profile"
          >
            Edit profile
          </button>
        </section>

        <section style={styles.countsSection} aria-label="User stats">
          <div style={styles.countItem}>
            <strong>{postsCount}</strong>
            <span>posts</span>
          </div>
          <div style={styles.countItem}>
            <strong>{followersCount}</strong>
            <span>followers</span>
          </div>
          <div style={styles.countItem}>
            <strong>{followingCount}</strong>
            <span>following</span>
          </div>
        </section>

        <section style={styles.postsSection} aria-label="Posts">
          <h3 style={styles.postsTitle}>Posts</h3>
          <div style={styles.postsGrid}>
            {postPhotos.map((key) => (
              <img
                key={key}
                src={`/runtime/photos/${key}.jpg`}
                alt="Post"
                style={styles.postPhoto}
              />
            ))}
          </div>
        </section>
      </main>
    );
  }

  // Edit profile page
  return (
    <main style={styles.main}>
      <header style={styles.editHeader}>
        <h2>Edit Profile</h2>
      </header>
      <form onSubmit={onSave} style={styles.form} noValidate>
        <label htmlFor="name" style={styles.label}>
          Name
          <input
            id="name"
            type="text"
            value={name}
            onChange={(e) => setName(e.target.value)}
            style={styles.input}
            aria-describedby={errors.name ? "name-error" : undefined}
          />
        </label>
        {errors.name && (
          <p id="name-error" role="alert" style={styles.error}>
            {errors.name}
          </p>
        )}

        <label htmlFor="handle" style={styles.label}>
          Handle
          <input
            id="handle"
            type="text"
            value={handle}
            onChange={(e) => setHandle(e.target.value)}
            style={styles.input}
            aria-describedby={errors.handle ? "handle-error" : undefined}
          />
        </label>
        {errors.handle && (
          <p id="handle-error" role="alert" style={styles.error}>
            {errors.handle}
          </p>
        )}

        <div style={styles.formButtons}>
          <button type="button" onClick={() => setPage("profile")} style={styles.cancelButton}>
            Cancel
          </button>
          <button type="submit" style={styles.saveButton}>
            Save
          </button>
        </div>
      </form>
    </main>
  );
}

